import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import {
  FiUser,
  FiMail,
  FiLock,
  FiShield,
  FiSave,
  FiCheckCircle,
  FiEye,
  FiEyeOff,
  FiCalendar,
  FiKey,
  FiActivity,
} from 'react-icons/fi';

import api, { getApiErrorMessage } from '../../services/api';
import { useAuth } from '../../hooks/useAuth';
import { useLanguage } from '../../contexts/LanguageContext';
import AdminCard from '../common/AdminCard';
import AdminLoading from '../common/AdminLoading';

const AdminProfile = () => {
  const { user, login } = useAuth();
  const { language } = useLanguage();
  const isKhmer = language === 'km' || language === 'kh';

  const [activeTab, setActiveTab] = useState('general'); // 'general' | 'password' | 'security'
  const [loading, setLoading] = useState(false);
  const [profileLoading, setProfileLoading] = useState(true);

  // Profile Form State
  const [profileData, setProfileData] = useState({
    username: '',
    email: '',
    role: '',
    created_at: '',
    updated_at: '',
    is_active: true,
  });

  // Password Form State
  const [passwordData, setPasswordData] = useState({
    current_password: '',
    new_password: '',
    confirm_password: '',
  });

  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [passwordLoading, setPasswordLoading] = useState(false);

  // Fetch latest current admin profile
  const fetchProfile = async () => {
    try {
      setProfileLoading(true);
      const res = await api.get('/api/auth/me');
      if (res.data) {
        setProfileData({
          username: res.data.username || '',
          email: res.data.email || '',
          role: res.data.role || 'admin',
          created_at: res.data.created_at || '',
          updated_at: res.data.updated_at || '',
          is_active: res.data.is_active !== undefined ? res.data.is_active : true,
        });
      }
    } catch (err) {
      console.error('Failed to load profile:', err);
      // Fallback to user from AuthContext
      if (user) {
        setProfileData({
          username: user.username || user.name || '',
          email: user.email || '',
          role: user.role || 'super_admin',
          created_at: user.created_at || '',
          updated_at: user.updated_at || '',
          is_active: true,
        });
      }
    } finally {
      setProfileLoading(false);
    }
  };

  useEffect(() => {
    fetchProfile();
  }, []);

  // Handle Profile Update Submit
  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    if (!profileData.username.trim() || !profileData.email.trim()) {
      toast.error(isKhmer ? 'សូមបំពេញឈ្មោះគណនី និងអ៊ីមែលឱ្យបានត្រឹមត្រូវ' : 'Please fill in username and email');
      return;
    }

    try {
      setLoading(true);
      const res = await api.put('/api/auth/profile', {
        username: profileData.username.trim(),
        email: profileData.email.trim(),
      });

      if (res.data) {
        toast.success(isKhmer ? 'បានកែប្រែព័ត៌មាន Profile ដោយជោគជ័យ!' : 'Profile updated successfully!');
        // Update local storage user if needed
        const storedUser = JSON.parse(localStorage.getItem('admin_user') || '{}');
        localStorage.setItem(
          'admin_user',
          JSON.stringify({
            ...storedUser,
            username: res.data.username,
            email: res.data.email,
          })
        );
      }
    } catch (err) {
      toast.error(getApiErrorMessage(err, isKhmer ? 'ការកែប្រែព័ត៌មានមិនជោគជ័យ' : 'Failed to update profile'));
    } finally {
      setLoading(false);
    }
  };

  // Handle Password Change Submit
  const handlePasswordSubmit = async (e) => {
    e.preventDefault();

    if (!passwordData.current_password) {
      toast.error(isKhmer ? 'សូមបញ្ចូលពាក្យសម្ងាត់បច្ចុប្បន្ន' : 'Please enter your current password');
      return;
    }

    if (passwordData.new_password.length < 8) {
      toast.error(isKhmer ? 'ពាក្យសម្ងាត់ថ្មីត្រូវមានយ៉ាងតិច ៨ តួអក្សរ' : 'New password must be at least 8 characters');
      return;
    }

    if (passwordData.new_password !== passwordData.confirm_password) {
      toast.error(isKhmer ? 'ពាក្យសម្ងាត់ថ្មី និងការបញ្ជាក់មិនត្រូវគ្នាឡើយ' : 'New password and confirmation do not match');
      return;
    }

    try {
      setPasswordLoading(true);
      await api.put('/api/auth/change-password', {
        current_password: passwordData.current_password,
        new_password: passwordData.new_password,
        confirm_password: passwordData.confirm_password,
      });

      toast.success(isKhmer ? 'បានប្តូរពាក្យសម្ងាត់ដោយជោគជ័យ!' : 'Password changed successfully!');
      setPasswordData({
        current_password: '',
        new_password: '',
        confirm_password: '',
      });
    } catch (err) {
      toast.error(getApiErrorMessage(err, isKhmer ? 'ការប្តូរពាក្យសម្ងាត់មិនជោគជ័យ' : 'Failed to change password'));
    } finally {
      setPasswordLoading(false);
    }
  };

  const firstLetter = profileData.username?.charAt(0)?.toUpperCase() || 'A';

  if (profileLoading) {
    return <AdminLoading fullScreen label={isKhmer ? 'កំពុងផ្ទុកព័ត៌មាន Profile...' : 'Loading profile...'} />;
  }

  return (
    <div className={`space-y-6 ${isKhmer ? 'font-khmer' : 'font-english'}`}>
      {/* PAGE HEADER */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl font-extrabold text-slate-900 tracking-tight flex items-center gap-3">
            <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-blue-50 text-[#2563EB]">
              <FiUser size={22} />
            </span>
            <span>{isKhmer ? 'ប្រវត្តិរូប Admin (Profile)' : 'Admin Profile'}</span>
          </h1>
          <p className="text-sm text-slate-500 mt-1">
            {isKhmer
              ? 'គ្រប់គ្រងព័ត៌មានផ្ទាល់ខ្លួន គណនី និងសុវត្ថិភាពពាក្យសម្ងាត់'
              : 'Manage your administrator account info, security and password settings'}
          </p>
        </div>
      </div>

      {/* HERO PROFILE SUMMARY CARD */}
      <div className="relative overflow-hidden rounded-3xl bg-gradient-to-r from-slate-900 via-blue-950 to-slate-900 text-white p-6 sm:p-8 shadow-xl border border-slate-800">
        {/* Subtle decorative ambient lights */}
        <div className="absolute -top-24 -right-24 w-72 h-72 bg-blue-500/20 rounded-full blur-3xl pointer-events-none" />
        <div className="absolute -bottom-24 -left-24 w-72 h-72 bg-indigo-500/15 rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10 flex flex-col sm:flex-row items-center sm:items-start gap-6 text-center sm:text-left">
          {/* Avatar Ring */}
          <div className="relative flex-shrink-0">
            <div className="w-24 h-24 sm:w-28 sm:h-28 rounded-2xl bg-gradient-to-tr from-blue-600 to-cyan-400 p-1 shadow-2xl flex items-center justify-center">
              <div className="w-full h-full rounded-xl bg-slate-900 flex items-center justify-center text-4xl font-extrabold text-white">
                {firstLetter}
              </div>
            </div>
            <span className="absolute bottom-1 right-1 w-5 h-5 rounded-full bg-emerald-500 border-2 border-slate-900 shadow-md" title="Active" />
          </div>

          {/* User Details */}
          <div className="flex-1 min-w-0">
            <div className="flex flex-wrap items-center justify-center sm:justify-start gap-2.5 mb-2">
              <h2 className="text-xl sm:text-2xl font-extrabold text-white tracking-tight">
                {profileData.username}
              </h2>
              <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-bold bg-blue-500/20 border border-blue-400/30 text-blue-300 backdrop-blur-md">
                <FiShield size={13} />
                <span className="uppercase">{profileData.role || 'Super Admin'}</span>
              </span>
              <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[11px] font-semibold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse" />
                <span>{isKhmer ? 'សកម្ម (Active)' : 'Active'}</span>
              </span>
            </div>

            <p className="text-sm text-slate-300 flex items-center justify-center sm:justify-start gap-2 mb-3">
              <FiMail size={15} className="text-blue-400" />
              <span>{profileData.email}</span>
            </p>

            <div className="flex flex-wrap items-center justify-center sm:justify-start gap-4 text-xs text-slate-400 pt-2 border-t border-slate-800">
              <span className="flex items-center gap-1.5">
                <FiCalendar size={13} />
                <span>
                  {isKhmer ? 'ថ្ងៃបង្កើត៖ ' : 'Created: '}
                  {profileData.created_at ? new Date(profileData.created_at).toLocaleDateString() : 'N/A'}
                </span>
              </span>
              <span className="flex items-center gap-1.5">
                <FiActivity size={13} />
                <span>{isKhmer ? 'ស្ថានភាព៖ គណនីមានសិទ្ធិពេញលេញ' : 'Access: Full Administrator Access'}</span>
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* TAB NAVIGATION */}
      <div className="flex border-b border-slate-200 bg-white rounded-2xl p-1.5 shadow-sm">
        <button
          type="button"
          onClick={() => setActiveTab('general')}
          className={`flex-1 py-3 px-4 rounded-xl text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition-all ${
            activeTab === 'general'
              ? 'bg-[#2563EB] text-white shadow-sm'
              : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
          }`}
        >
          <FiUser size={16} />
          <span>{isKhmer ? 'ព័ត៌មានទូទៅ (General Info)' : 'General Information'}</span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('password')}
          className={`flex-1 py-3 px-4 rounded-xl text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition-all ${
            activeTab === 'password'
              ? 'bg-[#2563EB] text-white shadow-sm'
              : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
          }`}
        >
          <FiLock size={16} />
          <span>{isKhmer ? 'ប្ដូរពាក្យសម្ងាត់ (Password)' : 'Change Password'}</span>
        </button>

        <button
          type="button"
          onClick={() => setActiveTab('security')}
          className={`flex-1 py-3 px-4 rounded-xl text-xs sm:text-sm font-bold flex items-center justify-center gap-2 transition-all ${
            activeTab === 'security'
              ? 'bg-[#2563EB] text-white shadow-sm'
              : 'text-slate-600 hover:bg-slate-50 hover:text-slate-900'
          }`}
        >
          <FiShield size={16} />
          <span>{isKhmer ? 'សុវត្ថិភាព & សិទ្ធិ (Security)' : 'Security & Roles'}</span>
        </button>
      </div>

      {/* TAB 1: GENERAL INFORMATION */}
      {activeTab === 'general' && (
        <AdminCard>
          <form onSubmit={handleProfileSubmit} className="space-y-6">
            <div>
              <h3 className="text-base font-bold text-slate-900 mb-1">
                {isKhmer ? 'កែប្រែព័ត៌មានគណនី' : 'Edit Profile Information'}
              </h3>
              <p className="text-xs text-slate-500">
                {isKhmer ? 'ព័ត៌មាននេះនឹងត្រូវបានបង្ហាញនៅក្នុងផ្ទាំងបញ្ជា Admin' : 'Update your administrator account identity'}
              </p>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  {isKhmer ? 'ឈ្មោះគណនី (Username)' : 'Username'} <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                    <FiUser size={16} />
                  </div>
                  <input
                    type="text"
                    value={profileData.username}
                    onChange={(e) => setProfileData({ ...profileData, username: e.target.value })}
                    required
                    className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-900 focus:border-[#2563EB] focus:ring-2 focus:ring-blue-100 outline-none transition"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  {isKhmer ? 'អ៊ីមែល (Email Address)' : 'Email Address'} <span className="text-red-500">*</span>
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                    <FiMail size={16} />
                  </div>
                  <input
                    type="email"
                    value={profileData.email}
                    onChange={(e) => setProfileData({ ...profileData, email: e.target.value })}
                    required
                    className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 text-sm font-medium text-slate-900 focus:border-[#2563EB] focus:ring-2 focus:ring-blue-100 outline-none transition"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  {isKhmer ? 'តួនាទី (Role)' : 'Role'}
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                    <FiShield size={16} />
                  </div>
                  <input
                    type="text"
                    value={profileData.role ? profileData.role.toUpperCase() : 'SUPER_ADMIN'}
                    disabled
                    className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-slate-200 bg-slate-50 text-sm font-bold text-slate-600 cursor-not-allowed"
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                  {isKhmer ? 'ស្ថានភាពគណនី (Status)' : 'Status'}
                </label>
                <div className="flex items-center h-[42px] px-4 rounded-xl border border-slate-200 bg-slate-50 text-emerald-600 text-xs font-bold gap-2">
                  <FiCheckCircle size={16} />
                  <span>{isKhmer ? 'គណនីកំពុងដំណើរការ (Active Account)' : 'Active Account'}</span>
                </div>
              </div>
            </div>

            <div className="pt-4 border-t border-slate-100 flex justify-end">
              <button
                type="submit"
                disabled={loading}
                className="h-11 px-6 bg-[#2563EB] hover:bg-[#1D4ED8] disabled:opacity-60 text-white rounded-xl text-xs font-bold inline-flex items-center gap-2 transition-all shadow-sm active:scale-95"
              >
                {loading ? (
                  <div className="w-4 h-4 rounded-full border-2 border-white border-t-transparent animate-spin" />
                ) : (
                  <FiSave size={16} />
                )}
                <span>{isKhmer ? 'រក្សាទុកការផ្លាស់ប្តូរ' : 'Save Changes'}</span>
              </button>
            </div>
          </form>
        </AdminCard>
      )}

      {/* TAB 2: CHANGE PASSWORD */}
      {activeTab === 'password' && (
        <AdminCard>
          <form onSubmit={handlePasswordSubmit} className="space-y-6 max-w-xl">
            <div>
              <h3 className="text-base font-bold text-slate-900 mb-1 flex items-center gap-2">
                <FiKey className="text-[#2563EB]" />
                <span>{isKhmer ? 'ប្តូរពាក្យសម្ងាត់គណនី' : 'Change Your Password'}</span>
              </h3>
              <p className="text-xs text-slate-500">
                {isKhmer
                  ? 'សូមជ្រើសរើសពាក្យសម្ងាត់ដែលមានសុវត្ថិភាព និងមានយ៉ាងតិច ៨ តួអក្សរ'
                  : 'Ensure your account uses a strong password of at least 8 characters'}
              </p>
            </div>

            {/* Current Password */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                {isKhmer ? 'ពាក្យសម្ងាត់បច្ចុប្បន្ន' : 'Current Password'} <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <FiLock size={16} />
                </div>
                <input
                  type={showCurrentPassword ? 'text' : 'password'}
                  value={passwordData.current_password}
                  onChange={(e) => setPasswordData({ ...passwordData, current_password: e.target.value })}
                  required
                  placeholder="••••••••"
                  className="w-full pl-10 pr-11 py-2.5 rounded-xl border border-slate-200 text-sm text-slate-900 focus:border-[#2563EB] focus:ring-2 focus:ring-blue-100 outline-none transition"
                />
                <button
                  type="button"
                  onClick={() => setShowCurrentPassword((prev) => !prev)}
                  className="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600"
                >
                  {showCurrentPassword ? <FiEyeOff size={16} /> : <FiEye size={16} />}
                </button>
              </div>
            </div>

            {/* New Password */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                {isKhmer ? 'ពាក្យសម្ងាត់ថ្មី' : 'New Password'} <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <FiLock size={16} />
                </div>
                <input
                  type={showNewPassword ? 'text' : 'password'}
                  value={passwordData.new_password}
                  onChange={(e) => setPasswordData({ ...passwordData, new_password: e.target.value })}
                  required
                  placeholder="••••••••"
                  minLength={8}
                  className="w-full pl-10 pr-11 py-2.5 rounded-xl border border-slate-200 text-sm text-slate-900 focus:border-[#2563EB] focus:ring-2 focus:ring-blue-100 outline-none transition"
                />
                <button
                  type="button"
                  onClick={() => setShowNewPassword((prev) => !prev)}
                  className="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600"
                >
                  {showNewPassword ? <FiEyeOff size={16} /> : <FiEye size={16} />}
                </button>
              </div>
              <p className="text-[11px] text-slate-400 mt-1">
                {isKhmer ? 'យ៉ាងតិច ៨ តួអក្សរ' : 'Minimum 8 characters'}
              </p>
            </div>

            {/* Confirm Password */}
            <div>
              <label className="block text-xs font-bold text-slate-700 uppercase tracking-wider mb-2">
                {isKhmer ? 'បញ្ជាក់ពាក្យសម្ងាត់ថ្មី' : 'Confirm New Password'} <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none text-slate-400">
                  <FiLock size={16} />
                </div>
                <input
                  type={showConfirmPassword ? 'text' : 'password'}
                  value={passwordData.confirm_password}
                  onChange={(e) => setPasswordData({ ...passwordData, confirm_password: e.target.value })}
                  required
                  placeholder="••••••••"
                  className="w-full pl-10 pr-11 py-2.5 rounded-xl border border-slate-200 text-sm text-slate-900 focus:border-[#2563EB] focus:ring-2 focus:ring-blue-100 outline-none transition"
                />
                <button
                  type="button"
                  onClick={() => setShowConfirmPassword((prev) => !prev)}
                  className="absolute inset-y-0 right-0 pr-3.5 flex items-center text-slate-400 hover:text-slate-600"
                >
                  {showConfirmPassword ? <FiEyeOff size={16} /> : <FiEye size={16} />}
                </button>
              </div>
            </div>

            <div className="pt-4 border-t border-slate-100 flex justify-end">
              <button
                type="submit"
                disabled={passwordLoading}
                className="h-11 px-6 bg-[#2563EB] hover:bg-[#1D4ED8] disabled:opacity-60 text-white rounded-xl text-xs font-bold inline-flex items-center gap-2 transition-all shadow-sm active:scale-95"
              >
                {passwordLoading ? (
                  <div className="w-4 h-4 rounded-full border-2 border-white border-t-transparent animate-spin" />
                ) : (
                  <FiSave size={16} />
                )}
                <span>{isKhmer ? 'ប្ដូរពាក្យសម្ងាត់ឥឡូវនេះ' : 'Update Password'}</span>
              </button>
            </div>
          </form>
        </AdminCard>
      )}

      {/* TAB 3: SECURITY & DETAILS */}
      {activeTab === 'security' && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <AdminCard>
            <h3 className="text-base font-bold text-slate-900 mb-4 flex items-center gap-2">
              <FiShield className="text-[#2563EB]" />
              <span>{isKhmer ? 'សិទ្ធិ & ការអនុញ្ញាត (Privileges)' : 'Security Privileges'}</span>
            </h3>

            <div className="space-y-3.5">
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងវគ្គសិក្សា (Courses)' : 'Manage Courses'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងវិចិត្រសាល (Gallery & Videos)' : 'Manage Media'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងការកំណត់ (Settings & Brand)' : 'Manage Settings'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
              <div className="flex items-center justify-between p-3.5 rounded-xl bg-slate-50 border border-slate-100">
                <span className="text-xs font-bold text-slate-700">{isKhmer ? 'គ្រប់គ្រងសារទំនាក់ទំនង (Messages)' : 'View Messages'}</span>
                <span className="px-2.5 py-1 rounded-md text-[10px] font-extrabold bg-emerald-100 text-emerald-800 uppercase">Granted</span>
              </div>
            </div>
          </AdminCard>

          <AdminCard>
            <h3 className="text-base font-bold text-slate-900 mb-4 flex items-center gap-2">
              <FiActivity className="text-[#2563EB]" />
              <span>{isKhmer ? 'ព័ត៌មានលម្អិតនៃគណនី' : 'Account Details'}</span>
            </h3>

            <div className="space-y-3.5 text-xs">
              <div className="flex justify-between py-2 border-b border-slate-100">
                <span className="text-slate-500">{isKhmer ? 'អត្តសញ្ញាណគណនី (ID)' : 'Account ID'}</span>
                <span className="font-mono font-bold text-slate-800">#ADM-{profileData.username}</span>
              </div>
              <div className="flex justify-between py-2 border-b border-slate-100">
                <span className="text-slate-500">{isKhmer ? 'កាលបរិច្ឆេទបង្កើត' : 'Account Created'}</span>
                <span className="font-medium text-slate-800">
                  {profileData.created_at ? new Date(profileData.created_at).toLocaleString() : 'System Default'}
                </span>
              </div>
              <div className="flex justify-between py-2 border-b border-slate-100">
                <span className="text-slate-500">{isKhmer ? 'កែប្រែចុងក្រោយ' : 'Last Updated'}</span>
                <span className="font-medium text-slate-800">
                  {profileData.updated_at ? new Date(profileData.updated_at).toLocaleString() : 'Just now'}
                </span>
              </div>
              <div className="flex justify-between py-2">
                <span className="text-slate-500">{isKhmer ? 'ស្ថានភាព Session' : 'Current Session'}</span>
                <span className="font-bold text-emerald-600 flex items-center gap-1.5">
                  <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping" />
                  <span>Authenticated & Active</span>
                </span>
              </div>
            </div>
          </AdminCard>
        </div>
      )}
    </div>
  );
};

export default AdminProfile;
